#Region @DOC
# Description:
# This process will create a static subset in a Hierarchy of target Dimension.

# Note:
# This process uses a number of parameters to determine what to include in the subset:
# - pConsol: If specified, only elements that are descendants of the consol will be included in
#   the subset. If blank, then this filter will be ignored.
# - pAttr: If specified, only elements that have a value equivalent to pAttrValue will be included
#   in the subset. If blank, this filter will be ignored.
# - pLevelFrom: Only elements with a level greater than or equal to pLevelFrom will be included in
#   the subset.
# - pLevelTo: Only elements with a level less than or equal to pLevelFrom will be included in the
#   subset.
# - pExclusions: If pExclusions is specified then the elements (separated by a delimiter) will be
#   excluded from the subset. Wildcards characters `*` and `?` are accepted.
# - pAddToSubset : If the specified subset already exists then this parameter will control whether
#   elements will be added to the existing subset (value 1) or a new subset will be created
#   (value 0).
#EndRegion @DOC

### Global Variables
pJson = IF( pJson @= '', '{}', pJson );
StringGlobalVariable(  'sBedrockReturnValue' );
NumericGlobalVariable( 'nBedrockReturnValue' );

### Constants ###
cThisProcName   = GetProcessName();
cUserName       = TM1User();
cTimeStamp      = TimSt( Now, '\Y\m\d\h\i\s' );
cRandomInt      = NumberToString( INT( RAND( ) * 1000000000 ));
cTemp           = cThisProcName |'_'| cTimeStamp |'_'| cRandomInt;
sErrors         = '[]';

#################################################################################################
#Region - Process Parameters

pDefaultParameters = '{
  "pAlias":               "",
  "pAttr":                "",
  "pAttrValue":           "",
  "pConsol":              "*",
  "pDelim":               "&",
  "pDimension":                 null,
  "pExclusions":          "",
  "pHierarchy":                "",
  "pSubset":                 null,
  "pAddToSubset":         0,
  "pLevelFrom":           0,
  "pLevelTo":             999,
  "pLogOutput":           0,
  "pStrictErrorHandling": 0,
  "pTemp":                1
}';

pPassedParameters = '{
  "pDimension":                 '|StringToJson  ( pDimension                 )|',
  "pHierarchy":                '|StringToJson  ( pHierarchy                )|',
  "pSubset":                 '|StringToJson  ( pSubset                 )|',
  "pLogOutput":           '|NumberToString( pLogOutput           )|',
  "pStrictErrorHandling": '|NumberToString( pStrictErrorHandling )|',
  "pTemp":                '|NumberToString( pTemp                )|'
}';

pJson = JsonMergePatch( pPassedParameters, pJson );
# String Parameters
pAlias               =                 JsonToString( JsonGet( pJson, 'pAlias'               ) );
pAttr                =                 JsonToString( JsonGet( pJson, 'pAttr'                ) );
pAttrValue           =                 JsonToString( JsonGet( pJson, 'pAttrValue'           ) );
pConsol              =                 JsonToString( JsonGet( pJson, 'pConsol'              ) );
pDelim               =                 JsonToString( JsonGet( pJson, 'pDelim'               ) );
pDimension                 =                 JsonToString( JsonGet( pJson, 'pDimension'                 ) );
pExclusions          =                 JsonToString( JsonGet( pJson, 'pExclusions'          ) );
pDefaultMDX          =                 JsonToString( JsonGet( pJson, 'pDefaultMDX'          ) );
pHierarchy                =                 JsonToString( JsonGet( pJson, 'pHierarchy'                ) );
pSubset                 =                 JsonToString( JsonGet( pJson, 'pSubset'                 ) );
# Numeric Parameters
pAddToSubset         = StringToNumber( JsonToString( JsonGet( pJson, 'pAddToSubset'         ) ) );
pLevelFrom           = StringToNumber( JsonToString( JsonGet( pJson, 'pLevelFrom'           ) ) );
pLevelTo             = StringToNumber( JsonToString( JsonGet( pJson, 'pLevelTo'             ) ) );
pLogOutput           = StringToNumber( JsonToString( JsonGet( pJson, 'pLogOutput'           ) ) );
pStrictErrorHandling = StringToNumber( JsonToString( JsonGet( pJson, 'pStrictErrorHandling' ) ) );
pTemp                = StringToNumber( JsonToString( JsonGet( pJson, 'pTemp'                ) ) );

### Get the parameters that differ from the default
pDiffer = JsonDiff( pDefaultParameters, pJson );
nSize = JsonSize( pDiffer );
WHILE( nSize > 0 );
  nSize = nSize - 1;
  pDiffer = JsonReplace( pDiffer, '/'|NumberToString( nSize )|'/op', '"add"' );
END;
pJson = JsonPatch( '{}', pDiffer );

IF( pLogOutput = 1 ); LogOutput('INFO', 'Passed Parameters: '|pPassedParameters ); ENDIF;

#EndRegion - Process Parameters
#################################################################################################

IF( pHierarchy @= '' );
  pHierarchy = pDimension;
ENDIF;

################################################################################################# 
#Region - Construct View

sDimension = pDimension;
sHierarchy = pHierarchy;
sFilter = pFilter;
sExcept = pExcept;
sDefaultMDX = pDefaultMDX;
sSubset = pSubset;

# Change sFilter to be JSON array
sFilterType = JsonType( sFilter );
IF( sFilterType @= 'object' );
  sFilter = JsonGet( sFilter, sDimension );
ELSEIF( sFilterType @= 'string' );
  sFilter = JsonAdd( '[]', 0, sFilter );
ELSEIF( sFilterType @<> 'array' );
  sFilter = JsonAdd( '[]', 0, StringToJson( sFilter ) );
ENDIF;

# Change sExcept to be JSON array
sExceptType = JsonType( sExcept );
IF( sExceptType @= 'object' );
  sExcept = JsonGet( sExcept, sDimension );
ELSEIF( sExceptType @= 'string' );
  sExcept = JsonAdd( '[]', 0, sExcept );
ELSEIF( sExceptType @<> 'array' );
  sExcept = JsonAdd( '[]', 0, StringToJson( sExcept ) );
ENDIF;

# Create Subset and set MDX
IF( SubsetExists( sDimension, sSubset ) = 0 );
  SubsetCreate( sDimension, sSubset, pTemp );
ENDIF;
SubsetMDXSet( sDimension, sSubset, '' );
IF( pAddToSubset = 0 );
  SubsetDeleteAllElements( sDimension, sSubset );
ENDIF;


# Loop through sFilter
SubsetCreate( sDimension, cTemp|'_mdx', 1 );
nSize = JsonSize( sFilter );
IF( nSize <= 0 & pAddToSubset = 0 );
  SubsetMDXSet( sDimension, sSubset, '{TM1FILTERBYLEVEL({TM1SUBSETALL(['|sDimension|'].['|sDimension|'])}, 0)}' );
  SubsetMDXSet( sDimension, sSubset, '' );
ENDIF;
  
WHILE( nSize > 0 );
  nSize = nSize - 1;
  sElement = JsontoString( sFilter, '/'|NumberToString( nSize ) );
  nIsMDX = IF( SUBST( sElement, 1, 1 ) @= '{' & SUBST( sElement, LONG( sElement ), 1 ) @= '}', 1, 0 );
  
  # Check if sElement is an element. If so, add it to the subset.
  IF( ElementIndex( sDimension, sHierarchy, sElement ) <> 0 );
    IF( SubsetElementExists( sDimension, sSubset, sElement ) = 0 );
      SubsetElementInsert( sDimension, sSubset, sElement, 0 );
    ENDIF;
  ELSEIF( nIsMDX = 1 % SubsetExists( sDimension, sElement ) = 1 );
    # Check if sElement is not a subset name
    IF( SubsetExists( sDimension, sElement ) = 0 );
      SubsetCreateByMDX( cTemp|'_subset', sElement, sDimension, 1 );
      sElement = cTemp|'_subset';
    ENDIF;
    # Loop through subset, adding each element
    nSubsetSize = SubsetGetSize( sDimension, sElement );
    WHILE( nSubsetSize > 0 );
      sSubsetElement = SubsetGetElementName( sDimension, sElement, nSubsetSize );
      IF( SubsetElementExists( sDimension, sSubset, sSubsetElement ) = 0 );
        SubsetElementInsert( sDimension, sSubset, sSubsetElement, 0 );
      ENDIF;
      nSubsetSize = nSubsetSize - 1;
    END;
  ENDIF;
END;

# Loop through sExcept
nSize = JsonSize( sExcept );
WHILE( nSize > 0 );
  nSize = nSize - 1;
  sElement = JsontoString( sExcept, '/'|NumberToString( nSize ) );
  nIsMDX = IF( SUBST( sElement, 1, 1 ) @= '{' & SUBST( sElement, LONG( sElement ), 1 ) @= '}', 1, 0 );
  
  # Check if sElement is an element. If so, add it to the subset.
  IF( ElementIndex( sDimension, sHierarchy, sElement ) <> 0 );
    WHILE( SubsetElementExists( sDimension, sSubset, sElement ) = 1 );
      nElementIndex = SubsetElementGetIndex( sDimension, sSubset, sElement, 1 );
      SubsetElementDelete( sDimension, sSubset, nElementIndex );
    END;
  ELSEIF( nIsMDX = 1 % SubsetExists( sDimension, sElement ) = 1 );
    # Check if sElement is not a subset name
    IF( SubsetExists( sDimension, sElement ) = 0 );
      SubsetCreateByMDX( cTemp|'_subset', sElement, sDimension, 1 );
      sElement = cTemp|'_subset';
    ENDIF;
    # Loop through subset, adding each element
    nSubsetSize = SubsetGetSize( sDimension, sElement );
    WHILE( nSubsetSize > 0 );
      sSubsetElement = SubsetGetElementName( sDimension, sElement, nSubsetSize );
      WHILE( SubsetElementExists( sDimension, sSubset, sSubsetElement ) = 1 );
        nElementIndex = SubsetElementGetIndex( sDimension, sSubset, sSubsetElement, 1 );
        SubsetElementDelete( sDimension, sSubset, nElementIndex );
      END;
      nSubsetSize = nSubsetSize - 1;
    END;
  ENDIF;
END;

#EndRegion - Construct View
################################################################################################# 

DatasourceNameForServer = sDimension;
DatasourceNameForClient = sDimension;
DatasourceDimensionSubset = sSubset;
